from __future__ import annotations
__doc__ = """Symbolic operator objects assembled from individual summands."""

from .summand import Summand


class Operator:
    """
    Operator base class representing a general operator as sum of summands"""

    def __init__(self, *summands):
        for summand in summands:
            assert isinstance(summand, Summand)
        self._summands = summands

    def __len__(self):
        return len(self._summands)

    @property
    def summands(self):
        """safe access to summands"""
        for summand in self._summands:
            yield summand.copy()
